# owner: platform
import unittest

from hourglass.rounding import rounded_labels
from hourglass.models import Span


class LabelTests(unittest.TestCase):
    def test_already_on_step(self):
        spans = [Span(9 * 60, 17 * 60 + 15)]
        self.assertEqual(
            rounded_labels(spans, 15),
            ["09:00-17:15 (8h 15m)"],
        )

    def test_rounds_to_nearest(self):
        spans = [Span(9 * 60 + 6, 17 * 60 + 8)]
        self.assertEqual(
            rounded_labels(spans, 15),
            ["09:00-17:15 (8h 15m)"],
        )

    def test_halfway_rounds_up(self):
        spans = [Span(7 * 60 + 30, 10 * 60 + 15)]
        self.assertEqual(
            rounded_labels(spans, 60),
            ["08:00-10:00 (2h 00m)"],
        )

    def test_many_spans_keep_order(self):
        spans = [Span(60, 125), Span(600, 660)]
        self.assertEqual(
            rounded_labels(spans, 5),
            [
                "01:00-02:05 (1h 05m)",
                "10:00-11:00 (1h 00m)",
            ],
        )

    def test_end_of_day(self):
        spans = [Span(23 * 60, 24 * 60 - 2)]
        self.assertEqual(
            rounded_labels(spans, 15),
            ["23:00-24:00 (1h 00m)"],
        )

    def test_empty_list(self):
        self.assertEqual(rounded_labels([], 15), [])


class BadStepTests(unittest.TestCase):
    def test_bad_steps_raise(self):
        for step in (0, -15, 7, 45, 61, 120):
            with self.subTest(step=step):
                with self.assertRaises(ValueError):
                    rounded_labels([Span(60, 120)], step)

    def test_bad_step_raises_without_spans(self):
        with self.assertRaises(ValueError):
            rounded_labels([], 0)

    def test_span_that_collapses_raises(self):
        with self.assertRaises(ValueError):
            rounded_labels([Span(61, 64)], 15)
